PRAGMA foreign_keys=ON; CREATE TABLE dim_date(date_key INTEGER PRIMARY KEY,full_date TEXT UNIQUE,month_name TEXT); CREATE TABLE dim_product(product_key INTEGER PRIMARY KEY,sku TEXT UNIQUE,name TEXT,category TEXT); CREATE TABLE fact_sales(id INTEGER PRIMARY KEY,date_key INTEGER REFERENCES dim_date(date_key),product_key INTEGER REFERENCES dim_product(product_key),qty INTEGER CHECK(qty>0),sales_amount REAL CHECK(sales_amount>=0));
